# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAMİYET\'TE TEMEL İBADETLER VE HİKMETLERİ</text>\n  <rect x="20" y="50" width="155" height="190" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Namaz (Salât)</text>\n  <text x="30" y="96" font-size="10" font-weight="bold" fill="#1d4ed8">• Türü: Bedenî İbadet</text>\n  <text x="30" y="116" font-size="10" fill="#334155">• Günde 5 vakit kıbleye</text>\n  <text x="38" y="130" font-size="10" fill="#334155">(Kâbe\'ye) yönelerek kılınır.</text>\n  <text x="30" y="152" font-size="10" fill="#334155">• Maddi-manevi temizlik ve</text>\n  <text x="38" y="166" font-size="10" fill="#334155">zaman bilinci kazandırır.</text>\n  <text x="30" y="188" font-size="10" font-weight="bold" fill="#1e40af">• Kötülüklerden alıkoyar</text>\n  <text x="38" y="202" font-size="10" fill="#334155">(Ankebût, 29/45).</text>\n\n  <rect x="190" y="50" width="155" height="190" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="267" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Oruç (Savm)</text>\n  <text x="200" y="96" font-size="10" font-weight="bold" fill="#166534">• Türü: Bedenî İbadet</text>\n  <text x="200" y="116" font-size="10" fill="#334155">• Ramazan ayında imsaktan</text>\n  <text x="208" y="130" font-size="10" fill="#334155">iftara kadar tutulur.</text>\n  <text x="200" y="152" font-size="10" fill="#334155">• Sabır, irade eğitimi ve</text>\n  <text x="208" y="166" font-size="10" fill="#334155">nimetlerin şükrünü öğretir.</text>\n  <text x="200" y="188" font-size="10" font-weight="bold" fill="#15803d">• Empati ve takva bilinci</text>\n  <text x="208" y="202" font-size="10" fill="#334155">(Bakara, 2/183).</text>\n\n  <rect x="360" y="50" width="155" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="437" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Zekât</text>\n  <text x="370" y="96" font-size="10" font-weight="bold" fill="#b45309">• Türü: Malî İbadet</text>\n  <text x="370" y="116" font-size="10" fill="#334155">• Nisap miktarı mala sahip</text>\n  <text x="378" y="130" font-size="10" fill="#334155">olanlar yılda bir verir.</text>\n  <text x="370" y="152" font-size="10" fill="#334155">• Cimriliği giderir, malı</text>\n  <text x="378" y="166" font-size="10" fill="#334155">temizler ve bereketlendirir.</text>\n  <text x="370" y="188" font-size="10" font-weight="bold" fill="#92400e">• Sosyal adalet ve sevgi</text>\n  <text x="378" y="202" font-size="10" fill="#334155">köprüsü kurar (Tevbe, 9/60).</text>\n\n  <rect x="530" y="50" width="150" height="190" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="605" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">4. Hac</text>\n  <text x="540" y="96" font-size="10" font-weight="bold" fill="#6d28d9">• Türü: Bedenî + Malî</text>\n  <text x="540" y="116" font-size="10" fill="#334155">• Zilhicce ayında Kâbe ve</text>\n  <text x="548" y="130" font-size="10" fill="#334155">Arafat\'ta eda edilir.</text>\n  <text x="540" y="152" font-size="10" fill="#334155">• İhramla makam ve ırk</text>\n  <text x="548" y="166" font-size="10" fill="#334155">ayrımlarını ortadan kaldırır.</text>\n  <text x="540" y="188" font-size="10" font-weight="bold" fill="#5b21b6">• Evrensel kardeşlik ve</text>\n  <text x="548" y="202" font-size="10" fill="#334155">mahşer bilinci kazandırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAMİYET\'TE KUTSAL ZAMANLAR, MEKÂNLAR VE DİNÎ MERASİMLER</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">Kutsal Mekânlar (Üç Mescit)</text>\n  <text x="30" y="98" font-size="10.5" font-weight="bold" fill="#075985">1. Mescid-i Harâm (Mekke):</text>\n  <text x="38" y="114" font-size="10" fill="#334155">Müslümanların kıblesi Kâbe\'nin</text>\n  <text x="38" y="128" font-size="10" fill="#334155">bulunduğu en kutsal mabet.</text>\n  <text x="30" y="150" font-size="10.5" font-weight="bold" fill="#075985">2. Mescid-i Nebevî (Medine):</text>\n  <text x="38" y="166" font-size="10" fill="#334155">Hz. Peygamber\'in mescidi ve</text>\n  <text x="38" y="180" font-size="10" fill="#334155">Ravza-i Mutahhara.</text>\n  <text x="30" y="202" font-size="10.5" font-weight="bold" fill="#075985">3. Mescid-i Aksâ (Kudüs):</text>\n  <text x="38" y="218" font-size="10" fill="#334155">Müslümanların ilk kıblesi.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Kutsal Gün, Gece ve Bayramlar</text>\n  <text x="255" y="98" font-size="10.5" font-weight="bold" fill="#b45309">• Haftalık Bayram: Cuma Günü</text>\n  <text x="263" y="114" font-size="10" fill="#334155">Hutbe ve cemaatle cuma namazı.</text>\n  <text x="255" y="138" font-size="10.5" font-weight="bold" fill="#b45309">• Ramazan Bayramı (Îdü\'l-Fıtr):</text>\n  <text x="263" y="154" font-size="10" fill="#334155">Oruç sonrası fıtır sadakası ve sevinç.</text>\n  <text x="255" y="178" font-size="10.5" font-weight="bold" fill="#b45309">• Kurban Bayramı (Îdü\'l-Edhâ):</text>\n  <text x="263" y="194" font-size="10" fill="#334155">Hac ve kurban paylaşımı (Zilhicce).</text>\n  <text x="255" y="218" font-size="10.5" font-weight="bold" fill="#b45309">• Kadir Gecesi ve Kandiller</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Hayat Dönemleri Merasimleri</text>\n  <text x="480" y="98" font-size="10.5" font-weight="bold" fill="#166534">• Doğum ve Çocukluk:</text>\n  <text x="488" y="114" font-size="10" fill="#334155">Kulağa ezan-kamet, güzel ad koyma,</text>\n  <text x="488" y="128" font-size="10" fill="#334155">akika kurbanı ve sünnet töreni.</text>\n  <text x="480" y="152" font-size="10.5" font-weight="bold" fill="#166534">• Evlilik: Nikâh Akdi</text>\n  <text x="488" y="168" font-size="10" fill="#334155">Şahitler huzurunda icap-kabul ve mehir.</text>\n  <text x="480" y="192" font-size="10.5" font-weight="bold" fill="#166534">• Vefat: Cenaze ve Taziye</text>\n  <text x="488" y="208" font-size="10" fill="#334155">Techiz, tekfin, cenaze namazı,</text>\n  <text x="488" y="222" font-size="10" fill="#334155">defin ve taziye dayanışması.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAMİYET\'TE İBADET - AHLAK BÜTÜNLÜĞÜ VE EVRENSEL İLKELER (MAKÂSID)</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İbadetlerin Ahlaki Gayeleri</text>\n  <text x="40" y="102" font-size="11" fill="#14532d">• Namaz: Kötülük ve fuhşiyattan korur.</text>\n  <text x="40" y="128" font-size="11" fill="#14532d">• Oruç: Yalandan ve kötü sözden sakındırır,</text>\n  <text x="48" y="144" font-size="10.5" fill="#166534">iradeyi ve merhameti güçlendirir.</text>\n  <text x="40" y="170" font-size="11" fill="#14532d">• Zekât ve İnfak: Bencillik ve cimriliği</text>\n  <text x="48" y="186" font-size="10.5" fill="#166534">yok eder, kardeşlik bağını kurar.</text>\n  <text x="40" y="212" font-size="11" fill="#14532d">• Hac: Irk ve sınıf üstünlüğünü siler.</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Korunan Beş Temel Hak (Zarûrât-ı Hamse)</text>\n  <rect x="382" y="90" width="276" height="132" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="395" y="112" font-size="11" font-weight="bold" fill="#1d4ed8">1. Canın Korunması (Hıfzu\'n-Nefs)</text>\n  <text x="395" y="134" font-size="11" font-weight="bold" fill="#1d4ed8">2. Aklın Korunması (Hıfzu\'l-Akl)</text>\n  <text x="395" y="156" font-size="11" font-weight="bold" fill="#1d4ed8">3. Dinin ve Vicdanın Korunması (Hıfzu\'d-Dîn)</text>\n  <text x="395" y="178" font-size="11" font-weight="bold" fill="#1d4ed8">4. Neslin ve Ailenin Korunması (Hıfzu\'n-Nesl)</text>\n  <text x="395" y="200" font-size="11" font-weight="bold" fill="#1d4ed8">5. Malın ve Emeğin Korunması (Hıfzu\'l-Mâl)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
